window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cecdea7b4ac88345"]={"versions": [{"id": "FIG-cecdea7b4ac88345", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Include-Hierarchie) des AUTOSAR Classic BSW-Moduls CAN Transport Layer (<code>CanTp</code>). Das Diagramm spezifiziert die Dateiabhängigkeiten zwischen Implementierungsdatei (<code>CanTp.c</code>), modulspezifischen Header-Dateien (<code>CanTp.h</code>, <code>CanTp_Cbk.h</code>, <code>CanTp_Cfg.h</code>), Basissoftware- bzw. Infrastruktur-Headern (<code>SchM_CanTp.h</code>, <code>MemMap.h</code>) sowie standardisierten Plattform- und Diagnose-Headern (<code>ComStack_Types.h</code>, <code>Std_Types.h</code>, <code>Dem.h</code>, <code>Dem_IntErrId.h</code>, <code>Det.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Dateientitäten und gerichtete Include-Abhängigkeiten (<code>includes</code>):</p>\n<ul class=\"fig-list\"><li><code>CanTp.c</code> bindet ein: <code>CanTp_Cfg.h</code>, <code>CanTp_Cbk.h</code>, <code>CanTp.h</code>, <code>SchM_CanTp.h</code> und <code>MemMap.h</code>.\n</li><li><code>CanTp.h</code> bindet ein: <code>ComStack_Types.h</code>, <code>MemMap.h</code>, <code>Dem.h</code> sowie bedingt <code>Det.h</code> (mit der Beschriftung <code>includes (if development error detection is turned on)</code>).\n</li><li><code>ComStack_Types.h</code> bindet <code>Std_Types.h</code> ein.\n</li><li><code>Dem.h</code> bindet <code>Dem_IntErrId.h (Event Id Symbols)</code> ein.\n</li><li><code>CanTp_Cfg.h</code> und <code>CanTp_Cbk.h</code> weisen keine ausgehenden Inklusionen auf.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Include-Gefüge zur Kompilierzeit; kein dynamisches Laufzeit- oder Sequenzverhalten. Die gerichteten Kanten determinieren die Übersetzungseinheit von <code>CanTp.c</code> sowie die transitive Typ- und Schnittstellensichtbarkeit über die Header. Inklusionskanten zu <code>MemMap.h</code> steuern die quellcodebasierte Speichersegmentierung (Pragma-gesteuertes Memory Mapping). Der Include von <code>Det.h</code> durch <code>CanTp.h</code> ist an die Vorkompilier-Bedingung einer aktiven Entwicklungsschleifenerkennung gekoppelt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[CANTP156]</code> ist die dargestellte Dateistruktur für die Implementierung des Moduls CanTp normativ verbindlich. <code>CanTp.h</code> stellt die externe API des Transport-Layers bereit und exportiert über die Inklusion von <code>ComStack_Types.h</code> grundlegende Kommunikationsdatentypen sowie über <code>Dem.h</code> und <code>Det.h</code> Diagnosedienst- und Fehlerschnittstellen. Modulinterne Implementierungsdetails, BSW-Scheduler-Hooks (<code>SchM_CanTp.h</code>) und Callback-Deklarationen (<code>CanTp_Cbk.h</code>) verbleiben isoliert in der Implementierungsdatei <code>CanTp.c</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7fb3c01ae4917a48", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Include-Hierarchie) des AUTOSAR Classic BSW-Moduls CAN Transport Layer (<code>CanTp</code>). Das Diagramm spezifiziert die Dateiabhängigkeiten zwischen Implementierungsdatei (<code>CanTp.c</code>), modulspezifischen Header-Dateien (<code>CanTp.h</code>, <code>CanTp_Cbk.h</code>, <code>CanTp_Cfg.h</code>), Basissoftware- bzw. Infrastruktur-Headern (<code>SchM_CanTp.h</code>, <code>MemMap.h</code>) sowie standardisierten Plattform- und Diagnose-Headern (<code>ComStack_Types.h</code>, <code>Std_Types.h</code>, <code>Dem.h</code>, <code>Dem_IntErrId.h</code>, <code>Det.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Dateientitäten und gerichtete Include-Abhängigkeiten (<code>includes</code>):</p>\n<ul class=\"fig-list\"><li><code>CanTp.c</code> bindet ein: <code>CanTp_Cfg.h</code>, <code>CanTp_Cbk.h</code>, <code>CanTp.h</code>, <code>SchM_CanTp.h</code> und <code>MemMap.h</code>.\n</li><li><code>CanTp.h</code> bindet ein: <code>ComStack_Types.h</code>, <code>MemMap.h</code>, <code>Dem.h</code> sowie bedingt <code>Det.h</code> (mit der Beschriftung <code>includes (if development error detection is turned on)</code>).\n</li><li><code>ComStack_Types.h</code> bindet <code>Std_Types.h</code> ein.\n</li><li><code>Dem.h</code> bindet <code>Dem_IntErrId.h (Event Id Symbols)</code> ein.\n</li><li><code>CanTp_Cfg.h</code> und <code>CanTp_Cbk.h</code> weisen keine ausgehenden Inklusionen auf.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Include-Gefüge zur Kompilierzeit; kein dynamisches Laufzeit- oder Sequenzverhalten. Die gerichteten Kanten determinieren die Übersetzungseinheit von <code>CanTp.c</code> sowie die transitive Typ- und Schnittstellensichtbarkeit über die Header. Inklusionskanten zu <code>MemMap.h</code> steuern die quellcodebasierte Speichersegmentierung (Pragma-gesteuertes Memory Mapping). Der Include von <code>Det.h</code> durch <code>CanTp.h</code> ist an die Vorkompilier-Bedingung einer aktiven Entwicklungsschleifenerkennung gekoppelt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[CANTP156]</code> ist die dargestellte Dateistruktur für die Implementierung des Moduls CanTp normativ verbindlich. <code>CanTp.h</code> stellt die externe API des Transport-Layers bereit und exportiert über die Inklusion von <code>ComStack_Types.h</code> grundlegende Kommunikationsdatentypen sowie über <code>Dem.h</code> und <code>Det.h</code> Diagnosedienst- und Fehlerschnittstellen. Modulinterne Implementierungsdetails, BSW-Scheduler-Hooks (<code>SchM_CanTp.h</code>) und Callback-Deklarationen (<code>CanTp_Cbk.h</code>) verbleiben isoliert in der Implementierungsdatei <code>CanTp.c</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7b9495657e4a6abd", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Include-Hierarchie) des AUTOSAR Classic BSW-Moduls CAN Transport Layer (<code>CanTp</code>). Das Diagramm spezifiziert die Dateiabhängigkeiten zwischen Implementierungsdatei (<code>CanTp.c</code>), modulspezifischen Header-Dateien (<code>CanTp.h</code>, <code>CanTp_Cbk.h</code>, <code>CanTp_Cfg.h</code>), Basissoftware- und Infrastruktur-Headern (<code>SchM_CanTp.h</code>, <code>MemMap.h</code>, <code>Det.h</code>) sowie standardisierten Plattform-Headern (<code>ComStack_Types.h</code>, <code>Std_Types.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Dateientitäten und gerichtete Include-Abhängigkeiten (<code>includes</code>):</p>\n<ul class=\"fig-list\"><li><code>CanTp.c</code> bindet ein: <code>CanTp_Cfg.h</code>, <code>CanTp_Cbk.h</code>, <code>CanTp.h</code>, <code>SchM_CanTp.h</code>, <code>MemMap.h</code> sowie bedingt <code>Det.h</code> (beschriftet mit <code>includes (if development error detection is turned on)</code>).\n</li><li><code>CanTp.h</code> bindet ausschließlich <code>ComStack_Types.h</code> ein.\n</li><li><code>ComStack_Types.h</code> bindet <code>Std_Types.h</code> ein.\n</li><li><code>CanTp_Cfg.h</code>, <code>CanTp_Cbk.h</code>, <code>SchM_CanTp.h</code>, <code>MemMap.h</code> und <code>Det.h</code> weisen keine ausgehenden Inklusionen im Diagramm auf.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Include-Gefüge zur Kompilierzeit; kein dynamisches Laufzeit- oder Sequenzverhalten. Die gerichteten Kanten determinieren die Übersetzungseinheit von <code>CanTp.c</code> sowie die transitive Typ- und Schnittstellensichtbarkeit. Die Inklusionsbeziehung von <code>CanTp.c</code> zu <code>Det.h</code> steht unter dem Vorbehalt aktivierter Entwicklungsschleifenerkennung (<code>if development error detection is turned on</code>). Speichersegmentierung erfolgt über die Einbindung von <code>MemMap.h</code> in <code>CanTp.c</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[CANTP156]</code> ist die dargestellte Dateistruktur für die Modulimplementierung normativ verbindlich. <code>CanTp.h</code> kapselt die Modulschnittstelle und bindet für Schnittstellendefinitionen ausschließlich <code>ComStack_Types.h</code> ein. Fehlerberichterstattung an das Default Error Tracer Modul (<code>Det.h</code>) wird aus der Implementierungsdatei <code>CanTp.c</code> heraus referenziert, wodurch die öffentliche Schnittstelle <code>CanTp.h</code> frei von Abhängigkeiten zu Diagnose- oder Fehlermelde-Headern bleibt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b94b74321d116924", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Dateistruktur- und Inklusionsdiagramm (Include-Hierarchie) des AUTOSAR Classic BSW-Moduls CAN Transport Layer (<code>CanTp</code>). Das Diagramm spezifiziert die Dateiabhängigkeiten zwischen Implementierungsdatei (<code>CanTp.c</code>), modulspezifischen Header-Dateien (<code>CanTp.h</code>, <code>CanTp_Cbk.h</code>, <code>CanTp_Cfg.h</code>), Basissoftware- und Infrastruktur-Headern (<code>SchM_CanTp.h</code>, <code>MemMap.h</code>, <code>Det.h</code>) sowie standardisierten Plattform-Headern (<code>ComStack_Types.h</code>, <code>Std_Types.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Dateientitäten und gerichtete Include-Abhängigkeiten (<code>includes</code>):</p>\n<ul class=\"fig-list\"><li><code>CanTp.c</code> bindet ein: <code>CanTp_Cfg.h</code>, <code>CanTp_Cbk.h</code>, <code>CanTp.h</code>, <code>SchM_CanTp.h</code>, <code>MemMap.h</code> und <code>Det.h</code> (jeweils mit einfacher <code>includes</code>-Beschriftung).\n</li><li><code>CanTp.h</code> bindet <code>ComStack_Types.h</code> ein.\n</li><li><code>ComStack_Types.h</code> bindet <code>Std_Types.h</code> ein.\n</li><li><code>CanTp_Cfg.h</code>, <code>CanTp_Cbk.h</code>, <code>SchM_CanTp.h</code>, <code>MemMap.h</code> und <code>Det.h</code> weisen keine ausgehenden Inklusionen auf.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Include-Gefüge zur Kompilierzeit; kein dynamisches Laufzeit- oder Sequenzverhalten. Die gerichteten Kanten bestimmen den Inklusionsbaum der Übersetzungseinheit <code>CanTp.c</code>. Alle Kanten tragen die einheitliche Relation <code>includes</code> ohne textuell annotierte Bedingungen im Diagramm.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[CANTP156]</code> ist die dargestellte Dateistruktur für die Modulimplementierung normativ verbindlich. <code>CanTp.h</code> kapselt die Modulschnittstelle und bindet für Schnittstellendefinitionen ausschließlich <code>ComStack_Types.h</code> ein. Fehlerberichterstattung an das Default Error Tracer Modul (<code>Det.h</code>) wird aus der Implementierungsdatei <code>CanTp.c</code> heraus referenziert, wodurch die öffentliche Schnittstelle <code>CanTp.h</code> frei von Abhängigkeiten zu Diagnose- oder Fehlermelde-Headern bleibt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cecdea7b4ac88345", "to": "FIG-7fb3c01ae4917a48", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7fb3c01ae4917a48", "to": "FIG-7b9495657e4a6abd", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Header-Dateien <code>Dem.h</code> und <code>Dem_IntErrId.h</code> inklusive der Include-Beziehung <code>CanTp.h</code> -&gt; <code>Dem.h</code> und <code>Dem.h</code> -&gt; <code>Dem_IntErrId.h</code> entfallen vollständig.\n</li><li>Die Include-Beziehung zu <code>Det.h</code> geht nicht mehr von <code>CanTp.h</code>, sondern direkt von <code>CanTp.c</code> aus.\n</li></ul>"}, {"from": "FIG-7b9495657e4a6abd", "to": "FIG-b94b74321d116924", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>An der Include-Beziehung von <code>CanTp.c</code> zu <code>Det.h</code> entfällt der erläuternde Bedingungstext <code>(if development error detection is turned on)</code>.\n</li></ul>"}]};
